mapper.select:
SELECT r.id as id, r.user_id as athleteId, u.name as athleteName, u.gender as gender, COALESCE(g.dept_name, g.class_name, g.major, g.college, g.grade) as deptName, u.email as contact, r.event_id as eventId, e.name as eventName, r.item_id as itemId, p.name as itemName, r.create_time as registrationTime, r.status as registrationStatus FROM registration r LEFT JOIN sys_user u ON r.user_id = u.id LEFT JOIN department g ON u.dept_id = g.id LEFT JOIN event e ON r.event_id = e.id LEFT JOIN event_item p ON r.item_id = p.id
AND r.event_id = #{eventId}
ORDER BY r.create_time DESC

SELECT r.id as id, r.id as registrationId, r.user_id as athleteId, u.name as athleteName, u.gender as gender, COALESCE(g.dept_name, g.class_name, g.major, g.college, g.grade) as deptName, u.email as contact, r.event_id as eventId, e.name as eventName, r.item_id as itemId, p.name as itemName, r.create_time as registrationTime, r.status as registrationStatus, s.id as scoreId, s.score_value as scoreValue, s.score_rank as scoreRank, NULL as remark, s.is_published as isPublished FROM registration r LEFT JOIN sys_user u ON r.user_id = u.id LEFT JOIN department g ON u.dept_id = g.id LEFT JOIN event e ON r.event_id = e.id LEFT JOIN event_item p ON r.item_id = p.id LEFT JOIN result s ON s.registration_id = r.id WHERE r.event_id = #{eventId} AND r.status IN ('APPROVED', 'CONFIRMED')
AND r.item_id = #{itemId}
ORDER BY p.id ASC, r.create_time DESC
